// Generated by scripts/build-component-sources.mjs from templates/components. Do not edit.
export const bundledComponentSources={
  "Counter": "// Откройте Add: измените умножение на params.step — результат изменится во всех вызовах.\n// Один исходник, независимое value у каждого подключения.\nconst component = {\n  name: \"Counter\",\n  parameters: {\n    type: \"object\",\n    properties: {\n      initial: { type: \"number\", default: 0, label: \"Начальное значение\" },\n      storySource: {\n        type: \"boolean\",\n        default: false,\n        label: \"Менять источник постоянной привязки явно\",\n      },\n      step: { type: \"number\", default: 1, label: \"Множитель изменения\" },\n    },\n  },\n  state: {\n    type: \"object\",\n    properties: { value: { type: \"number\", default: 0, label: \"Текущее значение\" } },\n  },\n  stateFromParameters: { value: \"initial\" },\n  signals: {\n    changed: {\n      name: \"Значение изменилось\",\n      payloadSchema: { type: \"object\", properties: { value: { type: \"number\" } } },\n    },\n  },\n  methods: {\n    add: {\n      name: \"Добавить\",\n      parameters: {\n        type: \"object\",\n        properties: { amount: { type: \"number\", default: 1, label: \"Количество\" } },\n      },\n      result: { type: \"number\" },\n      async run({ args, params, state, engine }) {\n        const next = state.value + args.amount * params.step;\n        if (params.storySource) await engine.writeBinding(\"value\", next);\n        else state.value = next;\n        await engine.emit(\"changed\", { value: state.value });\n        return state.value;\n      },\n    },\n    read: {\n      name: \"Прочитать\",\n      result: { type: \"number\" },\n      run({ state }) {\n        return state.value;\n      },\n    },\n    multiply: {\n      name: \"Умножить\",\n      parameters: {\n        type: \"object\",\n        properties: { factor: { type: \"number\", default: 2, label: \"Множитель\" } },\n      },\n      result: { type: \"number\" },\n      async run({ args, params, state, engine }) {\n        const next = state.value * args.factor;\n        if (params.storySource) await engine.writeBinding(\"value\", next);\n        else state.value = next;\n        await engine.emit(\"changed\", { value: state.value });\n        return state.value;\n      },\n    },\n  },\n};\n",
  "Reward": "// Упражнение: замените base * multiplier на base * multiplier + 5.\n// Получатель — явная ссылка на Counter, одинаковая логика для очков, монет и отношения.\n// Добавьте новый метод bonus с вызовом engine.invoke(refs.counter, \"add\", {amount: ...}).\nconst component = {\n  name: \"Reward\",\n  parameters: {\n    type: \"object\",\n    properties: {\n      base: { type: \"number\", default: 1, label: \"Базовая награда\" },\n      multiplier: { type: \"number\", default: 1, label: \"Множитель награды\" },\n    },\n  },\n  references: {\n    type: \"object\",\n    properties: {\n      counter: { type: \"reference\", referenceType: \"mechanic\", label: \"Куда начислять · Counter\" },\n    },\n  },\n  state: {\n    type: \"object\",\n    properties: { awards: { type: \"integer\", default: 0, label: \"Выдано наград\" } },\n  },\n  signals: {\n    awarded: {\n      name: \"Награда выдана\",\n      payloadSchema: {\n        type: \"object\",\n        properties: { amount: { type: \"number\" }, value: { type: \"number\" } },\n      },\n    },\n  },\n  methods: {\n    award: {\n      name: \"Начислить награду\",\n      parameters: {\n        type: \"object\",\n        properties: { factor: { type: \"number\", default: 1, label: \"Разовый множитель\" } },\n      },\n      result: { type: \"number\" },\n      async run({ args, params, refs, state, engine }) {\n        const amount = params.base * params.multiplier * args.factor;\n        const value = await engine.invoke(refs.counter, \"add\", { amount });\n        state.awards += 1;\n        await engine.emit(\"awarded\", { amount, value });\n        return value;\n      },\n    },\n  },\n};\n",
  "LockedDoor": "// Два подключения используют один исходник. Условия меняются здесь.\n// Упражнение: вместо count > 0 потребуйте count >= 2 или добавьте вызов Reward.award.\n// SetLocked(false) меняет только замок. Open — отдельная ожидаемая анимация.\nconst component = {\n  name: \"LockedDoor\",\n  parameters: {\n    type: \"object\",\n    properties: {\n      InitiallyLocked: { type: \"boolean\", default: true, label: \"Изначально заперта · IsLocked\" },\n      requiresKey: { type: \"boolean\", default: false, label: \"Разрешать открытие ключом\" },\n      consumeKey: { type: \"boolean\", default: false, label: \"Расходовать ключ\" },\n      OpenSeconds: { type: \"number\", min: 0, default: 0.5, label: \"Время открытия, сек\" },\n    },\n  },\n  state: {\n    type: \"object\",\n    properties: { IsLocked: { type: \"boolean\", default: true, label: \"Заперта · IsLocked\" } },\n  },\n  stateFromParameters: { IsLocked: \"InitiallyLocked\" },\n  references: {\n    type: \"object\",\n    properties: {\n      inventory: {\n        type: \"union\",\n        optional: true,\n        label: \"Инвентарь\",\n        variants: [\n          { type: \"reference\", referenceType: \"object\", label: \"Инвентарь объекта\" },\n          { type: \"reference\", referenceType: \"project\", label: \"Инвентарь проекта\" },\n        ],\n      },\n      key: { type: \"reference\", referenceType: \"item\", optional: true, label: \"Нужный ключ\" },\n    },\n  },\n  signals: { opened: { name: \"Дверь открыта\", payloadSchema: { type: \"object\", properties: {} } } },\n  methods: {\n    setLocked: {\n      name: \"Задать замок\",\n      parameters: {\n        type: \"object\",\n        properties: { value: { type: \"boolean\", default: false, label: \"Заперта\" } },\n      },\n      result: { type: \"boolean\" },\n      run({ args, state }) {\n        state.IsLocked = args.value;\n        return state.IsLocked;\n      },\n    },\n    canUnlock: {\n      name: \"Проверить ключ\",\n      result: { type: \"boolean\" },\n      async run({ params, refs, engine }) {\n        if (!params.requiresKey || !refs.inventory || !refs.key) return false;\n        const count = await engine.operation(\"sacura.inventory.count\", {\n          owner: refs.inventory,\n          item: refs.key,\n        });\n        return count > 0;\n      },\n    },\n    interact: {\n      name: \"Взаимодействовать\",\n      result: { type: \"boolean\" },\n      async run({ state, params, refs, engine, self }) {\n        if (state.IsLocked) {\n          if (!(await engine.invoke(self, \"canUnlock\", {}))) {\n            await engine.operation(\"sacura.game.message\", { message: \"Заперто\" });\n            return false;\n          }\n          if (params.consumeKey)\n            await engine.operation(\"sacura.inventory.remove\", {\n              owner: refs.inventory,\n              item: refs.key,\n              count: 1,\n            });\n          await engine.invoke(self, \"setLocked\", { value: false });\n        }\n        return await engine.invoke(self, \"open\", {});\n      },\n    },\n    open: {\n      name: \"Открыть\",\n      result: { type: \"boolean\" },\n      async run({ engine, owner, params }) {\n        await engine.operation(\"sacura.door.animate\", {\n          object: owner,\n          open: true,\n          seconds: params.OpenSeconds,\n        });\n        await engine.emit(\"opened\", {});\n        return true;\n      },\n    },\n  },\n};\n",
  "StoryFlag": "// Осмотр предмета явно меняет выбранную сюжетную переменную.\n// Упражнение: измените value:true на value:false — ветка чтения письма станет недоступна.\nconst component = {\n  name: \"StoryFlag\",\n  references: {\n    type: \"object\",\n    properties: {\n      variable: { type: \"reference\", referenceType: \"variable\", label: \"Сюжетный флаг\" },\n    },\n  },\n  methods: {\n    interact: {\n      name: \"Осмотреть и запомнить\",\n      result: { type: \"boolean\" },\n      async run({ refs, engine }) {\n        await engine.operation(\"sacura.variable.set\", { variable: refs.variable, value: true });\n        return true;\n      },\n    },\n  },\n};\n"
};
